package main

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

// ocbMainFile is a trimmed down version of the main.go generated by OCB. It
// contains the lines which the generator rewrites.
const ocbMainFile = `package main

func main() {
	info := component.BuildInfo{
		Command:     "alloy",
		Description: "Alloy OTel Collector distribution.",
		Version:     "1.20.0",
	}
}

func runInteractive(params otelcol.CollectorSettings) error {
	cmd := otelcol.NewCommand(params)
	return cmd.Execute()
}
`

func TestGenerate_AllPackage(t *testing.T) {
	tests := []struct {
		name string
		// alloy is the content of alloy-components.yaml.
		alloy string
		// expect is the expected content of all.go.
		expect string
	}{
		{
			name: "imports are sorted and deduplicated",
			alloy: `
components:
  - loki.write
  - loki.source.file
  - local.file_match
  - loki.write
`,
			expect: `// Code generated from collector/alloy-components.yaml by collector/generator. DO NOT EDIT.

// Package all imports the native Alloy components listed in
// collector/alloy-components.yaml.
package all

import (
	_ "github.com/grafana/alloy/internal/component/local/file_match" // Import local.file_match
	_ "github.com/grafana/alloy/internal/component/loki/source/file" // Import loki.source.file
	_ "github.com/grafana/alloy/internal/component/loki/write"       // Import loki.write
)
`,
		},
		{
			name:  "no components",
			alloy: `components: []`,
			expect: `// Code generated from collector/alloy-components.yaml by collector/generator. DO NOT EDIT.

// Package all imports the native Alloy components listed in
// collector/alloy-components.yaml.
package all
`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir, allDir := runGenerate(t, tt.alloy)
			require.Equal(t, tt.expect, readFile(t, allDir, "all.go"))
			require.Contains(t, readFile(t, dir, "main_alloy.go"), `_ "github.com/grafana/alloy/internal/component/all"`)
		})
	}
}

func TestGenerate_Converters(t *testing.T) {
	const converterImport = `_ "github.com/grafana/alloy/internal/converter/install"`

	tests := []struct {
		name   string
		alloy  string
		expect bool
	}{
		{name: "default to enabled", alloy: "components: []\n", expect: true},
		{name: "enabled", alloy: "components: []\nconverters: true\n", expect: true},
		{name: "disabled", alloy: "components: []\nconverters: false\n", expect: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir, _ := runGenerate(t, tt.alloy)
			main := readFile(t, dir, "main_alloy.go")
			if tt.expect {
				require.Contains(t, main, converterImport)
			} else {
				require.NotContains(t, main, converterImport)
			}
		})
	}
}

func TestGenerate_WithOTelEngine(t *testing.T) {
	dir, _ := runGenerate(t, "components: []\n")

	// The OCB main.go is rewritten to run the Alloy CLI with the OTel Engine
	// as a subcommand.
	main := readFile(t, dir, "main.go")
	require.Contains(t, main, "cmd := newAlloyCommand(params)")
	require.Contains(t, main, "Version:     CollectorVersion(),")
	require.NotContains(t, main, "otelcol.NewCommand")

	require.Contains(t, readFile(t, dir, "main_alloy.go"), "func newAlloyCommand(")
	require.Contains(t, readFile(t, dir, "main_alloy.go"), "otelsupervisor.NewCommand()")
	require.Contains(t, readFile(t, dir, "main_windows.go"), "//go:build windows")
}

func TestGenerate_Errors(t *testing.T) {
	tests := []struct {
		name      string
		alloy     string
		expectErr string
	}{
		{
			name:      "empty file",
			alloy:     "",
			expectErr: "components must be set to a list; use [] for no components",
		},
		{
			name:      "components without a value",
			alloy:     "components:\n#  - loki.write\n",
			expectErr: "components must be set to a list; use [] for no components",
		},
		{
			name:  "unknown components",
			alloy: "components: [loki.write, loki.wrte, foo.bar]",
			expectErr: `unknown components in alloy-components.yaml:
  "foo.bar" (no package internal/component/foo/bar)
  "loki.wrte" (no package internal/component/loki/wrte)`,
		},
		{
			name:      "component is an import",
			alloy:     "components:\n  - import: github.com/grafana/alloy/internal/component/loki/write\n",
			expectErr: "cannot unmarshal !!map into string",
		},
		{
			name:      "unknown key",
			alloy:     "components: []\nconverter: false\n",
			expectErr: "field converter not found",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir, allDir := setup(t, tt.alloy)
			err := generate(dir, filepath.Join(dir, "alloy-components.yaml"), allDir)
			require.ErrorContains(t, err, tt.expectErr)
		})
	}
}

func TestGenerate_AlloyComponentsFileNotFound(t *testing.T) {
	dir, allDir := setup(t, "")
	err := generate(dir, filepath.Join(dir, "does-not-exist.yaml"), allDir)
	require.ErrorContains(t, err, "read config:")
}

// runGenerate runs the generator against a fake OCB output directory, and
// returns its path and the path of the generated all package.
func runGenerate(t *testing.T, alloyComponents string) (dir, allDir string) {
	t.Helper()

	dir, allDir = setup(t, alloyComponents)
	require.NoError(t, generate(dir, filepath.Join(dir, "alloy-components.yaml"), allDir))
	return dir, allDir
}

// setup creates a directory which looks like OCB output, with the given
// alloy-components.yaml, and a fake internal/component directory. It returns
// the OCB output directory and the all package directory.
func setup(t *testing.T, alloyComponents string) (dir, allDir string) {
	t.Helper()

	dir = t.TempDir()
	files := map[string]string{
		"alloy-components.yaml": alloyComponents,
		"main.go":               ocbMainFile,
		"components.go":         "package main\n",
		"main_others.go":        "package main\n",
		"main_windows.go":       "package main\n",
	}
	for name, content := range files {
		require.NoError(t, os.WriteFile(filepath.Join(dir, name), []byte(content), 0o644))
	}

	// A fake internal/component directory with the components which tests
	// use. The generator only checks that their directories exist.
	componentDir := filepath.Join(t.TempDir(), "internal", "component")
	for _, rel := range []string{"all", "local/file_match", "loki/source/file", "loki/write"} {
		require.NoError(t, os.MkdirAll(filepath.Join(componentDir, filepath.FromSlash(rel)), 0o755))
	}
	return dir, filepath.Join(componentDir, "all")
}

func readFile(t *testing.T, dir, name string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(dir, name))
	require.NoError(t, err)
	return string(data)
}
